    98   * Look up the hostname and set user_host and user_shost.
    99   */
   100  void
   101  get_hostname(void)
   102  {
   103      char *cp;
   104      debug_decl(get_hostname, SUDOERS_DEBUG_UTIL);
   105
   106      if ((user_host = sudo_gethostname()) != NULL) {
   107          if ((cp = strchr(user_host, '.'))) {
   108              *cp = '\0';
   109              if ((user_shost = strdup(user_host)) == NULL)
   110                  sudo_fatalx(U_("%s: %s"), __func__, U_("unable to allocate memory"));
   111              *cp = '.';
   112          } else {
   113              user_shost = user_host;
   114          }
   115      } else {
   116          user_host = user_shost = strdup("localhost");
   117          if (user_host == NULL)
   118              sudo_fatalx(U_("%s: %s"), __func__, U_("unable to allocate memory"));
   119      }
   120      user_runhost = user_host;
   121      user_srunhost = user_shost;
   122
   123      debug_return;
   124  }
